-- Inventario por color/talla para el POS MarTextiles.
-- Ejecutar una sola vez en Supabase SQL Editor, después de las migraciones base del POS.
BEGIN;

CREATE TABLE IF NOT EXISTS public.pos_producto_variantes (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  producto_id bigint NOT NULL REFERENCES public.productos(id),
  color text,
  talla text,
  activo boolean NOT NULL DEFAULT true,
  creado_en timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT pos_variante_atributos_chk CHECK (NULLIF(btrim(color),'') IS NOT NULL OR NULLIF(btrim(talla),'') IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS pos_variante_producto_atributos_uq
  ON public.pos_producto_variantes(producto_id,lower(btrim(COALESCE(color,''))),lower(btrim(COALESCE(talla,''))));
CREATE INDEX IF NOT EXISTS pos_variantes_producto ON public.pos_producto_variantes(producto_id,activo);
ALTER TABLE public.pos_movimientos_inventario ADD COLUMN IF NOT EXISTS variante_id bigint REFERENCES public.pos_producto_variantes(id);
ALTER TABLE public.pos_venta_items ADD COLUMN IF NOT EXISTS variante_id bigint REFERENCES public.pos_producto_variantes(id);
ALTER TABLE public.pos_venta_items ADD COLUMN IF NOT EXISTS color text;
ALTER TABLE public.pos_venta_items ADD COLUMN IF NOT EXISTS talla text;

ALTER TABLE public.pos_producto_variantes ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='pos_producto_variantes' AND policyname='POS admin variantes') THEN
    CREATE POLICY "POS admin variantes" ON public.pos_producto_variantes FOR SELECT TO authenticated USING ((SELECT auth.uid())='c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid);
  END IF;
END $$;
REVOKE ALL ON public.pos_producto_variantes FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.pos_producto_variantes TO authenticated;

CREATE OR REPLACE FUNCTION public.pos_guardar_variantes(p_producto_id bigint,p_modo text,p_variantes jsonb,p_motivo text DEFAULT 'Configuración de variantes')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_row jsonb; v_color text; v_talla text; v_cantidad integer; v_variante bigint; v_actual integer; v_total integer:=0; v_legacy integer:=0; v_count integer:=0; v_ref text; v_existing_color boolean; v_existing_talla boolean; v_old record;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF p_modo IS NULL OR p_modo NOT IN ('ninguno','color','talla','color_talla') OR jsonb_typeof(p_variantes)<>'array' THEN RAISE EXCEPTION 'Modo o lista de variantes inválidos'; END IF;
  SELECT referencia INTO v_ref FROM public.productos WHERE id=p_producto_id AND COALESCE(eliminado,false)=false FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La referencia no existe o fue retirada'; END IF;
  IF p_modo='ninguno' THEN
    IF EXISTS(SELECT 1 FROM public.pos_producto_variantes WHERE producto_id=p_producto_id) THEN RAISE EXCEPTION 'Esta referencia ya tiene variantes e historial; conserva ese control para no perder trazabilidad'; END IF;
    RETURN jsonb_build_object('referencia',v_ref,'variantes',0,'existencia',public.pos_existencia(p_producto_id));
  END IF;
  SELECT COALESCE(bool_or(NULLIF(btrim(color),'') IS NOT NULL),false),COALESCE(bool_or(NULLIF(btrim(talla),'') IS NOT NULL),false)
  INTO v_existing_color,v_existing_talla FROM public.pos_producto_variantes WHERE producto_id=p_producto_id AND activo=true;
  IF v_existing_color OR v_existing_talla THEN
    IF (p_modo='color' AND (NOT v_existing_color OR v_existing_talla)) OR (p_modo='talla' AND (v_existing_color OR NOT v_existing_talla)) OR (p_modo='color_talla' AND (NOT v_existing_color OR NOT v_existing_talla)) THEN
      RAISE EXCEPTION 'Esta referencia ya está configurada por otro tipo de variante. Conserva el control actual para proteger el historial.';
    END IF;
  END IF;
  IF jsonb_array_length(p_variantes)=0 THEN RAISE EXCEPTION 'Agrega al menos una combinación de color o talla'; END IF;
  FOR v_row IN SELECT value FROM jsonb_array_elements(p_variantes) LOOP
    v_color:=NULLIF(btrim(v_row->>'color'),''); v_talla:=NULLIF(btrim(v_row->>'talla'),''); v_cantidad:=COALESCE(NULLIF(v_row->>'cantidad','')::integer,0);
    IF v_cantidad<0 THEN RAISE EXCEPTION 'La existencia no puede ser negativa'; END IF;
    IF p_modo='color' AND (v_color IS NULL OR v_talla IS NOT NULL) THEN RAISE EXCEPTION 'Para control por color, cada fila debe tener solo color'; END IF;
    IF p_modo='talla' AND (v_talla IS NULL OR v_color IS NOT NULL) THEN RAISE EXCEPTION 'Para control por talla, cada fila debe tener solo talla'; END IF;
    IF p_modo='color_talla' AND (v_color IS NULL OR v_talla IS NULL) THEN RAISE EXCEPTION 'Para control por color y talla, completa ambos datos en cada fila'; END IF;
    IF EXISTS(SELECT 1 FROM public.pos_producto_variantes x WHERE x.producto_id=p_producto_id AND lower(btrim(COALESCE(x.color,'')))=lower(COALESCE(v_color,'')) AND lower(btrim(COALESCE(x.talla,'')))=lower(COALESCE(v_talla,'')) AND x.activo=false) THEN RAISE EXCEPTION 'Una combinación anterior fue retirada; usa una combinación nueva para conservar el historial'; END IF;
    INSERT INTO public.pos_producto_variantes(producto_id,color,talla,activo)
    VALUES(p_producto_id,v_color,v_talla,true)
    ON CONFLICT(producto_id,lower(btrim(COALESCE(color,''))),lower(btrim(COALESCE(talla,'')))) DO UPDATE SET activo=true
    RETURNING id INTO v_variante;
    SELECT COALESCE(sum(cantidad),0)::integer INTO v_actual FROM public.pos_movimientos_inventario WHERE variante_id=v_variante;
    IF v_actual<>v_cantidad THEN
      INSERT INTO public.pos_movimientos_inventario(producto_id,variante_id,tipo,cantidad,nota)
      VALUES(p_producto_id,v_variante,'ajuste',v_cantidad-v_actual,COALESCE(NULLIF(btrim(p_motivo),''),'Conteo físico de variantes'));
    END IF;
    v_total:=v_total+v_cantidad; v_count:=v_count+1;
  END LOOP;
  FOR v_old IN SELECT id,color,talla FROM public.pos_producto_variantes WHERE producto_id=p_producto_id AND activo=true LOOP
    IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_variantes) x WHERE lower(btrim(COALESCE(x->>'color','')))=lower(btrim(COALESCE(v_old.color,''))) AND lower(btrim(COALESCE(x->>'talla','')))=lower(btrim(COALESCE(v_old.talla,'')))) THEN
      SELECT COALESCE(sum(cantidad),0)::integer INTO v_actual FROM public.pos_movimientos_inventario WHERE variante_id=v_old.id;
      IF v_actual<>0 THEN RAISE EXCEPTION 'No puedes quitar % con % unidades; ajústala a cero primero',concat_ws(' / ',v_old.color,v_old.talla),v_actual; END IF;
      IF EXISTS(SELECT 1 FROM public.pos_venta_items WHERE variante_id=v_old.id) THEN RAISE EXCEPTION 'La combinación % ya tiene ventas en su historial; déjala registrada con existencia cero',concat_ws(' / ',v_old.color,v_old.talla); END IF;
      UPDATE public.pos_producto_variantes SET activo=false WHERE id=v_old.id;
    END IF;
  END LOOP;
  SELECT COALESCE(sum(cantidad),0)::integer INTO v_legacy FROM public.pos_movimientos_inventario WHERE producto_id=p_producto_id AND variante_id IS NULL;
  IF v_legacy<>0 THEN
    INSERT INTO public.pos_movimientos_inventario(producto_id,tipo,cantidad,nota)
    VALUES(p_producto_id,'ajuste',-v_legacy,'Traslado del inventario general al control por variantes');
  END IF;
  RETURN jsonb_build_object('referencia',v_ref,'variantes',v_count,'existencia',v_total);
END $$;

CREATE OR REPLACE FUNCTION public.pos_crear_referencia_con_variantes(p_referencia text,p_nombre text,p_categoria text,p_costo numeric,p_cantidad_inicial integer,p_codigo_barras text,p_precios jsonb,p_modo text,p_variantes jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_producto_id bigint; v_nivel text; v_precio numeric; v_result jsonb; v_cantidad integer;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF NULLIF(btrim(p_referencia),'') IS NULL OR NULLIF(btrim(p_nombre),'') IS NULL THEN RAISE EXCEPTION 'La referencia y el nombre son obligatorios'; END IF;
  IF p_categoria NOT IN ('pijamas','Niños','Niñas','Joggers','Basicas') OR p_costo<0 OR p_cantidad_inicial<0 THEN RAISE EXCEPTION 'Revisa categoría, costo y existencia inicial'; END IF;
  IF jsonb_typeof(p_precios)<>'object' OR jsonb_typeof(p_variantes)<>'array' THEN RAISE EXCEPTION 'Revisa los precios A–E y las variantes'; END IF;
  IF EXISTS(SELECT 1 FROM public.productos WHERE lower(btrim(referencia::text))=lower(btrim(p_referencia))) THEN RAISE EXCEPTION 'Ya existe una referencia con ese código'; END IF;
  IF NULLIF(btrim(p_codigo_barras),'') IS NOT NULL AND EXISTS(SELECT 1 FROM public.pos_producto_config WHERE btrim(codigo_barras)=btrim(p_codigo_barras)) THEN RAISE EXCEPTION 'Ese código de barras ya está asignado'; END IF;
  INSERT INTO public.productos(referencia,nombre,categoria,subcategoria,descripcion,imagen_url,imagenes_url,publicado,eliminado)
  VALUES(btrim(p_referencia),btrim(p_nombre),p_categoria,NULL,NULL,NULL,'{}'::text[],false,false) RETURNING id INTO v_producto_id;
  INSERT INTO public.pos_producto_config(producto_id,codigo_barras,costo_unitario) VALUES(v_producto_id,NULLIF(btrim(p_codigo_barras),''),p_costo);
  FOREACH v_nivel IN ARRAY ARRAY['A','B','C','D','E'] LOOP
    v_precio:=NULLIF(p_precios->>v_nivel,'')::numeric;
    IF v_precio IS NULL OR v_precio<0 THEN RAISE EXCEPTION 'El precio de categoría % no es válido',v_nivel; END IF;
    INSERT INTO public.pos_producto_precios_clase(producto_id,nivel,precio_unitario) VALUES(v_producto_id,v_nivel,v_precio);
  END LOOP;
  IF p_modo='ninguno' THEN
    IF jsonb_array_length(p_variantes)>0 THEN RAISE EXCEPTION 'Quita las variantes o selecciona su tipo de control'; END IF;
    IF p_cantidad_inicial>0 THEN INSERT INTO public.pos_movimientos_inventario(producto_id,tipo,cantidad,nota) VALUES(v_producto_id,'entrada',p_cantidad_inicial,'Inventario inicial al crear la referencia'); END IF;
    v_cantidad:=p_cantidad_inicial;
  ELSE
    v_result:=public.pos_guardar_variantes(v_producto_id,p_modo,p_variantes,'Inventario inicial al crear la referencia');
    v_cantidad:=COALESCE((v_result->>'existencia')::integer,0);
  END IF;
  RETURN jsonb_build_object('producto_id',v_producto_id,'referencia',btrim(p_referencia),'existencia',v_cantidad);
END $$;

CREATE OR REPLACE FUNCTION public.pos_registrar_movimiento_variante(p_producto_id bigint,p_variante_id bigint,p_tipo text,p_cantidad integer,p_nota text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_ref text; v_actual integer; v_delta integer; v_color text; v_talla text;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF p_tipo NOT IN ('entrada','ajuste') OR p_cantidad<0 OR (p_tipo='entrada' AND p_cantidad=0) THEN RAISE EXCEPTION 'Tipo o cantidad inválidos'; END IF;
  SELECT referencia INTO v_ref FROM public.productos WHERE id=p_producto_id AND COALESCE(eliminado,false)=false FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Referencia no encontrada'; END IF;
  SELECT color,talla INTO v_color,v_talla FROM public.pos_producto_variantes WHERE id=p_variante_id AND producto_id=p_producto_id AND activo=true FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'La combinación de color y talla no está activa para esta referencia'; END IF;
  SELECT COALESCE(sum(cantidad),0)::integer INTO v_actual FROM public.pos_movimientos_inventario WHERE variante_id=p_variante_id;
  v_delta:=CASE WHEN p_tipo='entrada' THEN p_cantidad ELSE p_cantidad-v_actual END;
  IF v_delta<>0 THEN INSERT INTO public.pos_movimientos_inventario(producto_id,variante_id,tipo,cantidad,nota) VALUES(p_producto_id,p_variante_id,p_tipo,v_delta,NULLIF(btrim(p_nota),'')); END IF;
  RETURN jsonb_build_object('referencia',v_ref,'color',v_color,'talla',v_talla,'existencia',v_actual+v_delta,'diferencia',v_delta);
END $$;

CREATE OR REPLACE FUNCTION public.pos_registrar_venta(p_items jsonb,p_pagos jsonb,p_cliente jsonb DEFAULT '{}'::jsonb,p_nivel_precio text DEFAULT NULL,p_observacion text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_venta_id bigint; v_total numeric(14,2):=0; v_pagado numeric(14,2):=0; v_item jsonb; v_pago jsonb; v_producto record; v_cantidad integer; v_precio numeric(12,2); v_existencia integer; v_variante_id bigint; v_color text; v_talla text;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF p_nivel_precio IS NOT NULL AND p_nivel_precio NOT IN ('A','B','C','D','E') THEN RAISE EXCEPTION 'Categoría de precio inválida'; END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Agrega al menos una referencia'; END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items))<>(SELECT count(DISTINCT ((x->>'producto_id')||':'||COALESCE(x->>'variante_id','0'))) FROM jsonb_array_elements(p_items) x) THEN RAISE EXCEPTION 'Cada combinación debe aparecer una sola vez en el carrito'; END IF;
  IF p_pagos IS NULL OR jsonb_typeof(p_pagos)<>'array' OR jsonb_array_length(p_pagos)=0 THEN RAISE EXCEPTION 'Registra al menos un pago'; END IF;
  PERFORM 1 FROM public.productos p JOIN (SELECT DISTINCT (x->>'producto_id')::bigint id FROM jsonb_array_elements(p_items) x) i ON i.id=p.id ORDER BY p.id FOR UPDATE OF p;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_cantidad:=NULLIF(v_item->>'cantidad','')::integer; v_precio:=NULLIF(v_item->>'precio_unitario','')::numeric; v_variante_id:=NULLIF(v_item->>'variante_id','')::bigint;
    IF v_cantidad IS NULL OR v_cantidad<=0 OR v_precio IS NULL OR v_precio<0 THEN RAISE EXCEPTION 'Cantidad o precio inválido'; END IF;
    SELECT p.id,p.referencia,p.nombre,COALESCE(c.costo_unitario,0) costo_unitario,COALESCE(p.eliminado,false) eliminado INTO v_producto FROM public.productos p LEFT JOIN public.pos_producto_config c ON c.producto_id=p.id WHERE p.id=(v_item->>'producto_id')::bigint;
    IF NOT FOUND OR v_producto.eliminado THEN RAISE EXCEPTION 'Una referencia ya no está disponible'; END IF;
    IF EXISTS(SELECT 1 FROM public.pos_producto_variantes WHERE producto_id=v_producto.id AND activo=true) THEN
      IF v_variante_id IS NULL THEN RAISE EXCEPTION 'Selecciona color/talla para Ref %',v_producto.referencia; END IF;
      SELECT color,talla INTO v_color,v_talla FROM public.pos_producto_variantes WHERE id=v_variante_id AND producto_id=v_producto.id AND activo=true FOR UPDATE;
      IF NOT FOUND THEN RAISE EXCEPTION 'La combinación seleccionada ya no existe para Ref %',v_producto.referencia; END IF;
      SELECT COALESCE(sum(cantidad),0)::integer INTO v_existencia FROM public.pos_movimientos_inventario WHERE variante_id=v_variante_id;
    ELSE
      IF v_variante_id IS NOT NULL THEN RAISE EXCEPTION 'La combinación seleccionada no pertenece a Ref %',v_producto.referencia; END IF;
      v_color:=NULL;v_talla:=NULL;v_existencia:=public.pos_existencia(v_producto.id);
    END IF;
    IF v_existencia<v_cantidad THEN RAISE EXCEPTION 'Stock insuficiente para Ref % %, disponible: %',v_producto.referencia,concat_ws(' / ',v_color,v_talla),v_existencia; END IF;
    v_total:=v_total+(v_cantidad*v_precio);
  END LOOP;
  FOR v_pago IN SELECT value FROM jsonb_array_elements(p_pagos) LOOP
    IF v_pago->>'medio' IS NULL OR v_pago->>'medio' NOT IN ('efectivo','transferencia','tarjeta','otro') OR COALESCE((v_pago->>'valor')::numeric,0)<=0 THEN RAISE EXCEPTION 'Revisa los medios y valores de pago'; END IF;
    IF v_pago->>'medio'='efectivo' AND COALESCE((v_pago->>'valor_recibido')::numeric,(v_pago->>'valor')::numeric)<(v_pago->>'valor')::numeric THEN RAISE EXCEPTION 'El efectivo recibido no puede ser menor al valor aplicado'; END IF;
    IF v_pago->>'medio'='transferencia' AND NULLIF(btrim(COALESCE(v_pago->>'referencia_pago','')),'') IS NULL THEN RAISE EXCEPTION 'Cada transferencia necesita su número de referencia'; END IF;
    v_pagado:=v_pagado+(v_pago->>'valor')::numeric;
  END LOOP;
  IF round(v_pagado,2)<>round(v_total,2) THEN RAISE EXCEPTION 'Los pagos deben sumar exactamente el total de la venta'; END IF;
  INSERT INTO public.pos_ventas(cliente_nombre,cliente_documento,cliente_telefono,cliente_ciudad,nivel_precio,subtotal,total,observacion)
  VALUES(NULLIF(btrim(p_cliente->>'nombre'),''),NULLIF(btrim(p_cliente->>'documento'),''),NULLIF(btrim(p_cliente->>'telefono'),''),NULLIF(btrim(p_cliente->>'ciudad'),''),p_nivel_precio,v_total,v_total,NULLIF(btrim(p_observacion),'')) RETURNING id INTO v_venta_id;
  UPDATE public.pos_ventas SET numero='V-'||to_char(now(),'YYYY')||'-'||lpad(v_venta_id::text,6,'0') WHERE id=v_venta_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_cantidad:=(v_item->>'cantidad')::integer;v_precio:=(v_item->>'precio_unitario')::numeric;v_variante_id:=NULLIF(v_item->>'variante_id','')::bigint;
    SELECT p.id,p.referencia,p.nombre,COALESCE(c.costo_unitario,0) costo_unitario INTO v_producto FROM public.productos p LEFT JOIN public.pos_producto_config c ON c.producto_id=p.id WHERE p.id=(v_item->>'producto_id')::bigint;
    SELECT color,talla INTO v_color,v_talla FROM public.pos_producto_variantes WHERE id=v_variante_id;
    INSERT INTO public.pos_venta_items(venta_id,producto_id,variante_id,color,talla,referencia,nombre,cantidad,precio_unitario,costo_unitario)
    VALUES(v_venta_id,v_producto.id,v_variante_id,v_color,v_talla,v_producto.referencia,v_producto.nombre,v_cantidad,v_precio,COALESCE(v_producto.costo_unitario,0));
    INSERT INTO public.pos_movimientos_inventario(producto_id,variante_id,tipo,cantidad,venta_id,nota)
    VALUES(v_producto.id,v_variante_id,'venta',-v_cantidad,v_venta_id,'Venta '||v_venta_id);
  END LOOP;
  FOR v_pago IN SELECT value FROM jsonb_array_elements(p_pagos) LOOP
    INSERT INTO public.pos_pagos(venta_id,medio,valor,valor_recibido,cambio,banco,referencia_pago)
    VALUES(v_venta_id,v_pago->>'medio',(v_pago->>'valor')::numeric,CASE WHEN v_pago->>'medio'='efectivo' THEN COALESCE((v_pago->>'valor_recibido')::numeric,(v_pago->>'valor')::numeric) ELSE NULL END,CASE WHEN v_pago->>'medio'='efectivo' THEN GREATEST(COALESCE((v_pago->>'valor_recibido')::numeric,(v_pago->>'valor')::numeric)-(v_pago->>'valor')::numeric,0) ELSE 0 END,NULLIF(btrim(v_pago->>'banco'),''),NULLIF(btrim(v_pago->>'referencia_pago'),''));
  END LOOP;
  RETURN jsonb_build_object('id',v_venta_id,'numero',(SELECT numero FROM public.pos_ventas WHERE id=v_venta_id),'total',v_total);
END $$;

CREATE OR REPLACE FUNCTION public.pos_registrar_devolucion(p_venta_id bigint,p_items jsonb,p_motivo text,p_nota text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_devolucion_id bigint; v_item jsonb; v_cantidad integer; v_vendido integer; v_devuelto integer; v_linea record; v_total numeric(14,2):=0; v_estado text;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF NULLIF(btrim(p_motivo),'') IS NULL OR jsonb_typeof(p_items)<>'array' OR jsonb_array_length(p_items)=0 THEN RAISE EXCEPTION 'Indica el motivo y las referencias devueltas'; END IF;
  PERFORM 1 FROM public.pos_ventas WHERE id=p_venta_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Venta no encontrada'; END IF;
  INSERT INTO public.pos_devoluciones(venta_id,valor,motivo,nota) VALUES(p_venta_id,0,btrim(p_motivo),NULLIF(btrim(p_nota),'')) RETURNING id INTO v_devolucion_id;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
    v_cantidad:=(v_item->>'cantidad')::integer;IF v_cantidad<=0 THEN RAISE EXCEPTION 'Cantidad devuelta inválida'; END IF;
    SELECT id,cantidad,precio_unitario,producto_id,variante_id INTO v_linea FROM public.pos_venta_items WHERE id=(v_item->>'venta_item_id')::bigint AND venta_id=p_venta_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'El artículo no pertenece a esta venta'; END IF;
    SELECT COALESCE(sum(di.cantidad),0)::integer INTO v_devuelto FROM public.pos_devolucion_items di JOIN public.pos_devoluciones d ON d.id=di.devolucion_id WHERE d.venta_id=p_venta_id AND di.venta_item_id=v_linea.id;
    v_vendido:=v_linea.cantidad-v_devuelto;IF v_cantidad>v_vendido THEN RAISE EXCEPTION 'La cantidad supera las unidades pendientes de devolución'; END IF;
    INSERT INTO public.pos_devolucion_items(devolucion_id,venta_item_id,cantidad,reintegrar_inventario,valor_linea) VALUES(v_devolucion_id,v_linea.id,v_cantidad,COALESCE((v_item->>'reintegrar_inventario')::boolean,false),v_cantidad*v_linea.precio_unitario);
    IF COALESCE((v_item->>'reintegrar_inventario')::boolean,false) THEN INSERT INTO public.pos_movimientos_inventario(producto_id,variante_id,tipo,cantidad,venta_id,nota) VALUES(v_linea.producto_id,v_linea.variante_id,'devolucion',v_cantidad,p_venta_id,'Devolución '||v_devolucion_id); END IF;
    v_total:=v_total+(v_cantidad*v_linea.precio_unitario);
  END LOOP;
  UPDATE public.pos_devoluciones SET valor=v_total WHERE id=v_devolucion_id;
  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM public.pos_venta_items vi WHERE vi.venta_id=p_venta_id AND vi.cantidad>COALESCE((SELECT sum(di.cantidad) FROM public.pos_devolucion_items di JOIN public.pos_devoluciones d ON d.id=di.devolucion_id WHERE d.venta_id=p_venta_id AND di.venta_item_id=vi.id),0)) THEN 'devuelta' ELSE 'devuelta_parcial' END INTO v_estado;
  UPDATE public.pos_ventas SET estado=v_estado WHERE id=p_venta_id;
  RETURN jsonb_build_object('devolucion_id',v_devolucion_id,'valor',v_total,'estado',v_estado);
END $$;

-- Las anulaciones también reintegran cada unidad a su combinación original.
CREATE OR REPLACE FUNCTION public.pos_anular_venta(p_venta_id bigint,p_motivo text,p_nota text DEFAULT NULL,p_reintegrar_inventario boolean DEFAULT true,p_reembolsar_efectivo boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_estado text;v_numero text;v_cliente_id bigint;v_efectivo numeric(14,2):=0;v_saldo_favor numeric(14,2):=0;v_caja_id bigint;
BEGIN
  IF auth.uid() IS DISTINCT FROM 'c1fd6ad7-15be-42a6-b239-0564bb34cba5'::uuid THEN RAISE EXCEPTION 'No autorizado'; END IF;
  IF NULLIF(btrim(p_motivo),'') IS NULL THEN RAISE EXCEPTION 'Selecciona el motivo de anulación'; END IF;
  SELECT estado,numero,cliente_id INTO v_estado,v_numero,v_cliente_id FROM public.pos_ventas WHERE id=p_venta_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Venta no encontrada'; END IF;
  IF v_estado<>'completada' THEN RAISE EXCEPTION 'Solo se pueden anular ventas completadas sin devoluciones parciales'; END IF;
  IF EXISTS(SELECT 1 FROM public.pos_devoluciones WHERE venta_id=p_venta_id) THEN RAISE EXCEPTION 'Esta venta ya tiene devoluciones; no se puede anular completa'; END IF;
  SELECT COALESCE(sum(valor) FILTER(WHERE medio='efectivo'),0),COALESCE(sum(valor) FILTER(WHERE medio='saldo_favor'),0) INTO v_efectivo,v_saldo_favor FROM public.pos_pagos WHERE venta_id=p_venta_id;
  IF p_reembolsar_efectivo THEN
    IF v_efectivo<=0 THEN RAISE EXCEPTION 'Esta venta no tiene pagos en efectivo para reembolsar'; END IF;
    SELECT id INTO v_caja_id FROM public.pos_cajas WHERE estado='abierta' ORDER BY id DESC LIMIT 1 FOR UPDATE;
    IF v_caja_id IS NULL THEN RAISE EXCEPTION 'Abre la caja para registrar el reembolso en efectivo'; END IF;
    IF v_efectivo>(SELECT saldo_inicial+COALESCE(sum(CASE WHEN direccion='ingreso' THEN monto ELSE -monto END),0) FROM public.pos_movimientos_caja WHERE caja_id=v_caja_id AND tipo<>'apertura') THEN RAISE EXCEPTION 'No hay efectivo suficiente en caja para registrar el reembolso'; END IF;
    INSERT INTO public.pos_movimientos_caja(caja_id,tipo,direccion,monto,venta_id,nota) VALUES(v_caja_id,'retiro','egreso',v_efectivo,p_venta_id,'Reembolso por anulación de '||COALESCE(v_numero,p_venta_id::text));
  END IF;
  IF p_reintegrar_inventario THEN
    PERFORM 1 FROM public.productos p JOIN public.pos_venta_items vi ON vi.producto_id=p.id WHERE vi.venta_id=p_venta_id ORDER BY p.id FOR UPDATE OF p;
    INSERT INTO public.pos_movimientos_inventario(producto_id,variante_id,tipo,cantidad,venta_id,nota)
    SELECT producto_id,variante_id,'ajuste',cantidad,p_venta_id,'Reintegro por anulación de '||COALESCE(v_numero,p_venta_id::text) FROM public.pos_venta_items WHERE venta_id=p_venta_id;
  END IF;
  IF v_saldo_favor>0 AND v_cliente_id IS NOT NULL THEN
    INSERT INTO public.pos_movimientos_cuenta_cliente(cliente_id,tipo,monto,medio,venta_id,nota) VALUES(v_cliente_id,'abono',v_saldo_favor,'otro',p_venta_id,'Saldo a favor restaurado por anulación de '||COALESCE(v_numero,p_venta_id::text));
  END IF;
  UPDATE public.pos_ventas SET estado='anulada',anulada_en=now(),motivo_anulacion=btrim(p_motivo),nota_anulacion=NULLIF(btrim(p_nota),''),inventario_reintegrado=COALESCE(p_reintegrar_inventario,true),efectivo_reembolsado=CASE WHEN p_reembolsar_efectivo THEN v_efectivo ELSE 0 END WHERE id=p_venta_id;
  RETURN jsonb_build_object('id',p_venta_id,'numero',v_numero,'estado','anulada','inventario_reintegrado',COALESCE(p_reintegrar_inventario,true),'efectivo_reembolsado',CASE WHEN p_reembolsar_efectivo THEN v_efectivo ELSE 0 END,'saldo_favor_restaurado',v_saldo_favor);
END $$;

REVOKE ALL ON FUNCTION public.pos_guardar_variantes(bigint,text,jsonb,text),public.pos_crear_referencia_con_variantes(text,text,text,numeric,integer,text,jsonb,text,jsonb),public.pos_registrar_movimiento_variante(bigint,bigint,text,integer,text),public.pos_registrar_venta(jsonb,jsonb,jsonb,text,text),public.pos_registrar_devolucion(bigint,jsonb,text,text),public.pos_anular_venta(bigint,text,text,boolean,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pos_guardar_variantes(bigint,text,jsonb,text),public.pos_crear_referencia_con_variantes(text,text,text,numeric,integer,text,jsonb,text,jsonb),public.pos_registrar_movimiento_variante(bigint,bigint,text,integer,text),public.pos_registrar_venta(jsonb,jsonb,jsonb,text,text),public.pos_registrar_devolucion(bigint,jsonb,text,text),public.pos_anular_venta(bigint,text,text,boolean,boolean) TO authenticated;
COMMIT;
